add_filter( 'show_admin_bar', 'perfectpixel_hide_admin_bar_for_roles', 20 );

function perfectpixel_hide_admin_bar_for_roles( $show ) {
	$user = wp_get_current_user();
	if ( ! $user->exists() ) {
		return $show;
	}
	$roles = array_filter( array_map( 'trim', explode( ',', '{{hide_admin_bar_roles}}' ) ) );
	return array_intersect( $roles, (array) $user->roles ) && ! current_user_can( 'manage_woocommerce' ) ? false : $show;
}
